using System.IO;
using NeoCompose.Runtime.Json;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using NUnit.Framework;

namespace NeoCompose.Tests
{
    /// <summary>
    /// Newtonsoft.Json round-trip coverage for <see cref="ProjectData"/>
    /// and the full IR tree rooted on <see cref="Attribute.getter"/>.
    ///
    /// Two fixtures back the suite:
    ///
    ///  - <c>synth-example.json</c> — generated by the TS-side dump
    ///    script (`scripts/dump-synth-export.ts`). Designed to exercise
    ///    every IR variant: list / dict literals, force-unwrap,
    ///    isCheck, callGetter, coalesce, where / count functions, both
    ///    arithmetic + boolean operations, and the four instruction
    ///    kinds (variable / if / return / throw, plus the bare
    ///    <c>return;</c> null-pointer case).
    ///  - <c>project-example.json</c> — a real-world export captured
    ///    from a live Neo-Compose authoring session.
    ///
    /// Tests load each fixture from
    /// <c>Packages/com.ryanbliss.neocompose/Tests/</c> (the canonical
    /// Unity Package Manager path for local-path references and
    /// registry installs alike) and pass the JSON through
    /// <see cref="JsonConvert.DeserializeObject{T}(string)"/>.
    /// </summary>
    public class ProjectExportRoundTripTests
    {
        private const string PackageRoot =
            "Packages/com.ryanbliss.neocompose/Tests";

        private static string LoadFixture(string fileName)
        {
            return File.ReadAllText(Path.Combine(PackageRoot, fileName));
        }

        private static ProjectData Deserialize(string json)
        {
            return JsonConvert.DeserializeObject<ProjectData>(json);
        }

        // --------------------------------------------------------------
        // Synthesized fixture — exercises every IR variant.
        // --------------------------------------------------------------

        [Test]
        public void SynthFixture_DeserializesIntoProjectExport()
        {
            var export = Deserialize(LoadFixture("synth-example.json"));

            Assert.IsNotNull(export);
            Assert.IsNotNull(export.project);
            Assert.IsNotNull(export.attributes);
            Assert.IsNotNull(export.values);
            Assert.IsNotNull(export.types);
            Assert.IsNotNull(export.enums);
            Assert.IsNotNull(export.dialogues);
            Assert.IsNotNull(export.dialogueGroups);
            Assert.IsNotNull(export.priorityGroups);
            Assert.Greater(export.attributes.Count, 0);
        }

        [Test]
        public void SynthFixture_TimestampsRoundTripAsEpochNumbers()
        {
            var export = Deserialize(LoadFixture("synth-example.json"));

            Assert.AreEqual(0d, export.project.createdAt.EpochMilliseconds);
            Assert.AreEqual(0d, export.attributes["attr-name"].updatedAt.EpochMilliseconds);
            Assert.AreEqual(0d, export.values["v-num"].createdAt.EpochMilliseconds);

            var serialized = JObject.Parse(JsonConvert.SerializeObject(export.project));
            Assert.AreNotEqual(JTokenType.String, serialized["createdAt"]!.Type);
            Assert.AreEqual(0d, serialized["createdAt"]!.Value<double>());
        }

        [Test]
        public void MissingDialogueMaps_DeserializeToEmptyDictionaries()
        {
            var json = @"
{
  ""project"": {
    ""_id"": ""project-a"",
    ""id"": ""project-a"",
    ""name"": ""Older Export"",
    ""rootAssetsAttributeId"": ""assets-root"",
    ""rootSaveFileAttributeId"": ""save-root"",
    ""createdAt"": ""1970-01-01T00:00:00.000Z"",
    ""updatedAt"": ""1970-01-01T00:00:00.000Z""
  },
  ""attributes"": {},
  ""values"": {},
  ""types"": {},
  ""enums"": {}
}";
            var export = Deserialize(json);
            Assert.IsNotNull(export.dialogues);
            Assert.IsNotNull(export.dialogueGroups);
            Assert.IsNotNull(export.priorityGroups);
            Assert.IsNotNull(export.files);
            Assert.IsNotNull(export.textureTemplates);
            Assert.IsNotNull(export.audioClipTemplates);
            Assert.IsNotNull(export.tileGridContents);
            Assert.AreEqual(0, export.dialogues.Count);
            Assert.AreEqual(0, export.dialogueGroups.Count);
            Assert.AreEqual(0, export.priorityGroups.Count);
            Assert.AreEqual(0, export.files.Count);
            Assert.AreEqual(0, export.textureTemplates.Count);
            Assert.AreEqual(0, export.audioClipTemplates.Count);
            Assert.AreEqual(0, export.tileGridContents.Count);
        }

        [Test]
        public void TileGridContents_DeserializeToWorldDto()
        {
            var json = @"
{
  ""project"": {
    ""_id"": ""project-a"",
    ""id"": ""project-a"",
    ""name"": ""World Export"",
    ""rootAssetsAttributeId"": ""assets-root"",
    ""rootSaveFileAttributeId"": ""save-root"",
    ""createdAt"": ""1970-01-01T00:00:00.000Z"",
    ""updatedAt"": ""1970-01-01T00:00:00.000Z""
  },
  ""attributes"": {},
  ""values"": {},
  ""types"": {},
  ""enums"": {},
  ""tileGridContents"": {
    ""town-grid"": {
      ""schemaVersion"": 1,
      ""manifest"": {
        ""id"": ""manifest-1"",
        ""gridValueId"": ""town-grid"",
        ""schemaVersion"": 1,
        ""regionSize"": 32,
        ""sourceVersionId"": null,
        ""layerOrder"": [""background-link""],
        ""importedAssets"": [],
        ""boundsHint"": { ""minX"": 0, ""minY"": 0, ""maxX"": 10, ""maxY"": 10 },
        ""contentHash"": ""manifest-hash""
      },
      ""regions"": [
        {
          ""id"": ""region-1"",
          ""gridValueId"": ""town-grid"",
          ""layerId"": ""background-link"",
          ""layerKind"": ""tile"",
          ""regionKey"": ""0,0"",
          ""regionX"": 0,
          ""regionY"": 0,
          ""dataSchemaVersion"": 1,
          ""data"": {
            ""kind"": ""tile"",
            ""instances"": [
              { ""id"": ""tile-1"", ""tileValueId"": ""grass"", ""position"": { ""x"": 1, ""y"": 2 } }
            ]
          },
          ""contentHash"": ""region-hash"",
          ""deleted"": false
        }
      ],
      ""tileLayerLinks"": [
        {
          ""id"": ""shop-floor-link-output"",
          ""gridValueId"": ""town-grid"",
          ""objectLayerId"": ""objects"",
          ""objectInstanceId"": ""shop-1"",
          ""objectValueId"": ""shop"",
          ""tileLayerLinkValueId"": ""shop-floor-link"",
          ""targetTileLayerId"": ""background-link"",
          ""origin"": { ""x"": 4, ""y"": 5 },
          ""order"": 10,
          ""tiles"": [
            {
              ""id"": ""shop-floor-0-0"",
              ""tileValueId"": ""wood-floor"",
              ""tileTypeId"": ""floor-tile"",
              ""position"": { ""x"": 0, ""y"": 0 },
              ""order"": 1
