        {
            var json = @"
{
  ""project"": {
    ""_id"": ""project-a"",
    ""id"": ""project-a"",
    ""name"": ""Dialogue Project"",
    ""rootAssetsAttributeId"": ""assets-root"",
    ""rootSaveFileAttributeId"": ""save-root"",
    ""createdAt"": ""1970-01-01T00:00:00.000Z"",
    ""updatedAt"": ""1970-01-01T00:00:00.000Z""
  },
  ""attributes"": {},
  ""enums"": {},
  ""types"": {},
  ""values"": {},
  ""dialogues"": {
    ""dialogue-a"": {
      ""_id"": ""dialogue-a"",
      ""id"": ""dialogue-a"",
