                        }
                      }
                    },
                    {
                      ""type"": ""collectionCall"",
                      ""target"": {
                        ""pointer"": { ""type"": ""reference"", ""valueId"": ""visited-value"" },
                        ""typeInfo"": {
                          ""type"": 8,
                          ""required"": true,
                          ""entryTypeInfo"": { ""type"": 4, ""required"": true }
                        },
                        ""writability"": ""save""
                      },
                      ""mutation"": ""Add"",
                      ""args"": [
                        {
                          ""type"": ""value"",
                          ""value"": {
                            ""typeInfo"": { ""type"": 4, ""required"": true },
                            ""value"": ""Earth""
                          }
                        }
                      ]
                    }
                  ]
                }
              }
            }
          ]
        },
        ""conditions-a"": {
          ""id"": ""conditions-a"",
          ""type"": 3,
          ""layout"": { ""x"": 0, ""y"": 280, ""width"": 320, ""height"": 120, ""isOpen"": true },
          ""linkedValues"": [],
